168	    /**
169	     * Builds the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
170	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters
171	     * of the owner's last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more
172	     * than the number of owners already in that city (e.g. {@code MAD-SMI-0007}).
173	     *
174	     * @param city     the owner's city
175	     * @param lastName the owner's last name
176	     * @return the assigned customer code
177	     */
178	    private String nextCustomerCode(String city, String lastName) {
179	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
180	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
181	        int sequence = (int) this.clinicService.findAllOwners().stream()
182	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
183	            .count() + 1;
184	        return String.format("%s-%s-%04d", city3, last3, sequence);
185	    }
186	
187	    /**
188	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
189	     * last two digits of the registrationDate year, zero-padded (e.g. {@code MAD-SMI-0007-M26}).
190	     *
191	     * @param customerCode     the owner's assigned customer code
192	     * @param registrationDate the owner's registration date
193	     * @return the assigned membership number
194	     */
195	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
196	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
197	    }
198	
199	    /**
200	     * Counts the existing owners that already share the given firstName and lastName, compared
201	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
202	     * the owners that pre-existed this create.
203	     *
204	     * @param firstName the new owner's first name
205	     * @param lastName  the new owner's last name
206	     * @return the number of existing namesakes
207	     */
208	    private int countNamesakes(String firstName, String lastName) {
209	        return (int) this.clinicService.findAllOwners().stream()
210	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
211	                && equalsIgnoreCase(existing.getLastName(), lastName))
212	            .count();
213	    }
214	
215	    /**
216	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
217	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
218	     * customer-code sequence is derived.
219	     *
220	     * @param city the new owner's city
221	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
222	     */
223	    private void rejectWhenCityAtCapacity(String city) {
224	        long count = this.clinicService.findAllOwners().stream()
225	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
226	            .count();
227	        if (count >= CITY_CAPACITY) {
228	            throw new CityAtCapacityException(city);
229	        }
230	    }
231	
232	    /**
233	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
234	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
235	     * business-day registration date, so the limit is enforced per business day and weekend
236	     * requests count against the Monday they roll forward to.
237	     *
238	     * @param registrationDate the owner's adjusted (business-day) registration date
239	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
240	     *                                  registration date
241	     */
242	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
243	        long count = this.clinicService.findAllOwners().stream()
244	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
245	            .count();
246	        if (count >= DAILY_OWNER_LIMIT) {
247	            throw new DailyOwnerLimitException(registrationDate);
248	        }
249	    }
250	
251	    /**
252	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
253	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
254	     * effective registration date (whether supplied in the request or defaulted to the server date)
255	     * so a weekend value never persists as an owner's {@code registrationDate}.
256	     *
257	     * @param date the effective registration date
258	     * @return the same date when it is a weekday, otherwise the next Monday
259	     */
260	    private LocalDate toBusinessDay(LocalDate date) {
261	        return switch (date.getDayOfWeek()) {
262	            case SATURDAY -> date.plusDays(2);
263	            case SUNDAY -> date.plusDays(1);
264	            default -> date;
265	        };
266	    }
