536	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
537	    @Override
538	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
539	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
540	        if (currentOwner != null) {
541	            Pet currentPet = this.clinicService.findPetById(petId);
542	            if (currentPet != null) {
543	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
